CREATE TYPE "bigu_app"."MessageSenderType" AS ENUM ('USER','ASSISTANT','SYSTEM');
CREATE TYPE "bigu_app"."MessageStatus" AS ENUM ('PENDING','COMPLETED','FAILED');
CREATE TYPE "bigu_app"."ContextChangeStatus" AS ENUM ('PENDING','APPROVED','REJECTED','CANCELLED');
CREATE TYPE "bigu_app"."ClientInstructionStatus" AS ENUM ('ACTIVE','ARCHIVED');
CREATE TYPE "bigu_app"."ClientFileStatus" AS ENUM ('UPLOADING','PROCESSING','READY_FOR_REVIEW','APPROVED','FAILED','REJECTED');
CREATE TABLE "bigu_app"."conversations" ("id" TEXT NOT NULL,"client_id" TEXT NOT NULL,"title" VARCHAR(200) NOT NULL DEFAULT 'Client workspace',"is_primary" BOOLEAN NOT NULL DEFAULT true,"created_by_id" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "conversations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "bigu_app"."messages" ("id" TEXT NOT NULL,"conversation_id" TEXT NOT NULL,"sender_type" "bigu_app"."MessageSenderType" NOT NULL,"content" TEXT NOT NULL,"status" "bigu_app"."MessageStatus" NOT NULL DEFAULT 'COMPLETED',"created_by_id" TEXT,"provider" VARCHAR(80),"model" VARCHAR(120),"prompt_version" VARCHAR(40),"used_fallback" BOOLEAN,"error_code" VARCHAR(80),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "messages_pkey" PRIMARY KEY ("id"));
CREATE TABLE "bigu_app"."context_change_requests" ("id" TEXT NOT NULL,"client_id" TEXT NOT NULL,"conversation_id" TEXT NOT NULL,"source_message_id" TEXT NOT NULL,"field_name" VARCHAR(80) NOT NULL,"old_value" TEXT,"proposed_value" TEXT NOT NULL,"explanation" TEXT,"confidence" DOUBLE PRECISION,"status" "bigu_app"."ContextChangeStatus" NOT NULL DEFAULT 'PENDING',"proposed_by_provider" VARCHAR(80),"proposed_by_model" VARCHAR(120),"prompt_version" VARCHAR(40),"reviewed_by_id" TEXT,"reviewed_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "context_change_requests_pkey" PRIMARY KEY ("id"));
CREATE TABLE "bigu_app"."client_instructions" ("id" TEXT NOT NULL,"client_id" TEXT NOT NULL,"title" VARCHAR(160) NOT NULL,"content" TEXT NOT NULL,"source_message_id" TEXT,"created_by_id" TEXT NOT NULL,"status" "bigu_app"."ClientInstructionStatus" NOT NULL DEFAULT 'ACTIVE',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "client_instructions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "bigu_app"."client_files" ("id" TEXT NOT NULL,"client_id" TEXT NOT NULL,"conversation_id" TEXT NOT NULL,"original_name" VARCHAR(255) NOT NULL,"stored_name" VARCHAR(255) NOT NULL,"mime_type" VARCHAR(120) NOT NULL,"size_bytes" INTEGER NOT NULL,"storage_url" VARCHAR(2048) NOT NULL,"processing_status" "bigu_app"."ClientFileStatus" NOT NULL DEFAULT 'UPLOADING',"extracted_text" TEXT,"uploaded_by_id" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "client_files_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "conversations_client_id_is_primary_key" ON "bigu_app"."conversations"("client_id","is_primary");
CREATE INDEX "conversations_client_id_updated_at_idx" ON "bigu_app"."conversations"("client_id","updated_at");
CREATE INDEX "messages_conversation_id_created_at_idx" ON "bigu_app"."messages"("conversation_id","created_at");
CREATE INDEX "context_change_requests_client_id_status_idx" ON "bigu_app"."context_change_requests"("client_id","status");
CREATE INDEX "client_instructions_client_id_status_idx" ON "bigu_app"."client_instructions"("client_id","status");
CREATE INDEX "client_files_client_id_processing_status_idx" ON "bigu_app"."client_files"("client_id","processing_status");
ALTER TABLE "bigu_app"."conversations" ADD CONSTRAINT "conversations_client_id_fkey" FOREIGN KEY ("client_id") REFERENCES "bigu_app"."clients"("id") ON DELETE CASCADE ON UPDATE CASCADE;
