ALTER TABLE "bigu_app"."context_change_requests" ADD CONSTRAINT "context_change_requests_conversation_id_fkey" FOREIGN KEY ("conversation_id") REFERENCES "bigu_app"."conversations"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "bigu_app"."context_change_requests" ADD CONSTRAINT "context_change_requests_source_message_id_fkey" FOREIGN KEY ("source_message_id") REFERENCES "bigu_app"."messages"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "bigu_app"."context_change_requests" ADD CONSTRAINT "context_change_requests_reviewed_by_id_fkey" FOREIGN KEY ("reviewed_by_id") REFERENCES "bigu_app"."User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "bigu_app"."client_instructions" ADD CONSTRAINT "client_instructions_client_id_fkey" FOREIGN KEY ("client_id") REFERENCES "bigu_app"."clients"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "bigu_app"."client_instructions" ADD CONSTRAINT "client_instructions_source_message_id_fkey" FOREIGN KEY ("source_message_id") REFERENCES "bigu_app"."messages"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "bigu_app"."client_instructions" ADD CONSTRAINT "client_instructions_created_by_id_fkey" FOREIGN KEY ("created_by_id") REFERENCES "bigu_app"."User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "bigu_app"."client_files" ADD CONSTRAINT "client_files_client_id_fkey" FOREIGN KEY ("client_id") REFERENCES "bigu_app"."clients"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "bigu_app"."client_files" ADD CONSTRAINT "client_files_conversation_id_fkey" FOREIGN KEY ("conversation_id") REFERENCES "bigu_app"."conversations"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "bigu_app"."client_files" ADD CONSTRAINT "client_files_uploaded_by_id_fkey" FOREIGN KEY ("uploaded_by_id") REFERENCES "bigu_app"."User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;